package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.jsonFormatVisitors.*;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.std.StdDateFormat;
import com.fasterxml.jackson.databind.util.StdDateFormat;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class DateTimeSerializerBase_createContextual_TriageGen2Test {

    private SerializerProvider serializers;
    private BeanProperty property;
    private TestDateTimeSerializer serializer;

    // Concrete implementation for testing abstract class
    private static class TestDateTimeSerializer extends DateTimeSerializerBase<Date> {
        private final Boolean useTimestamp;
        private final DateFormat customFormat;

        protected TestDateTimeSerializer(Class<Date> type, Boolean useTimestamp, DateFormat customFormat) {
            super(type, useTimestamp, customFormat);
            this.useTimestamp = useTimestamp;
            this.customFormat = customFormat;
        }

        @Override
        public JsonSerializer<?> withFormat(Boolean useTimestamp, DateFormat customFormat) {
            return new TestDateTimeSerializer(Date.class, useTimestamp, customFormat);
        }

        @Override
        public void serialize(Date value, com.fasterxml.jackson.core.JsonGenerator gen, SerializerProvider serializers) throws java.io.IOException {
        }

        @Override
        public boolean isEmpty(Date value) {
            return false;
        }

        @Override
        public boolean isEmpty(SerializerProvider serializers, Date value) {
            return false;
        }

        @Override
        protected long _timestamp(Date value) {
            return value.getTime();
        }

        @Override
        public com.fasterxml.jackson.databind.JsonNode getSchema(SerializerProvider serializers, com.fasterxml.jackson.databind.JavaType typeHint) {
            return null;
        }

        @Override
        public void acceptJsonFormatVisitor(com.fasterxml.jackson.databind.ser.std.JsonFormatVisitorWrapper visitor, com.fasterxml.jackson.databind.JavaType typeHint) throws JsonMappingException {
        }

        // Mocking the protected method findFormatOverrides which is part of the base class logic
        // Since we cannot easily mock a protected method of the class under test without Spy, 
        // we rely on the fact that in a real Jackson environment, this looks at annotations.
        // For this unit test, we will use a Spy to control findFormatOverrides.
    }

    private TestDateTimeSerializer spySerializer;

    @Before
    public void setUp() {
        serializers = mock(SerializerProvider.class);
        property = mock(BeanProperty.class);
        serializer = new TestDateTimeSerializer(Date.class, false, null);
        spySerializer = spy(serializer);

        when(serializers.getLocale()).thenReturn(Locale.US);
        when(serializers.getTimeZone()).thenReturn(TimeZone.getTimeZone("UTC"));
    }

    @Test
    public void testCreateContextual_PropertyNull() throws JsonMappingException {
        JsonSerializer<?> result = spySerializer.createContextual(serializers, null);
        assertSame(spySerializer, result);
    }

    @Test
    public void testCreateContextual_NoFormatOverrides() throws JsonMappingException {
        doReturn(null).when(spySerializer).findFormatOverrides(any(), any(), any());

        JsonSerializer<?> result = spySerializer.createContextual(serializers, property);
        assertSame(spySerializer, result);
    }

    @Test
    public void testCreateContextual_NumericShape() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.NUMBER_INT);
        doReturn(format).when(spySerializer).findFormatOverrides(any(), any(), any());

        JsonSerializer<?> result = spySerializer.createContextual(serializers, property);

        assertNotSame(spySerializer, result);
        // In the real code, withFormat(Boolean.TRUE, null) is called.
        // Our implementation returns a new instance.
    }

    @Test
    public void testCreateContextual_StringShapeWithPattern() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(true);
        when(format.getPattern()).thenReturn("yyyy-MM-dd");
        when(format.hasLocale()).thenReturn(false);
        when(format.hasTimeZone()).thenReturn(false);
        doReturn(format).when(spySerializer).findFormatOverrides(any(), any(), any());

        JsonSerializer<?> result = spySerializer.createContextual(serializers, property);

        assertNotSame(spySerializer, result);
        // Since we can't easily inspect the private field of the returned object without reflection,
        // we verify that it didn't return 'this'. 
        // In a real scenario, one would use reflection to check the DateFormat inside 'result'.
    }

    @Test
    public void testCreateContextual_StringShapeWithLocaleAndTimeZone() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(true);
        when(format.getLocale()).thenReturn(Locale.FRANCE);
        when(format.hasTimeZone()).thenReturn(true);
        when(format.getTimeZone()).thenReturn(TimeZone.getTimeZone("GMT"));
        doReturn(format).when(spySerializer).findFormatOverrides(any(), any(), any());

        JsonSerializer<?> result = spySerializer.createContextual(serializers, property);

        assertNotSame(spySerializer, result);
    }

    @Test
    public void testCreateContextual_FallbackToSerializers() throws JsonMappingException {
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(false);
        when(format.hasTimeZone()).thenReturn(false);
        doReturn(format).when(spySerializer).findFormatOverrides(any(), any(), any());

        // This triggers the part where it uses serializers.getLocale() and serializers.getTimeZone()
        JsonSerializer<?> result = spySerializer.createContextual(serializers, property);

        assertNotSame(spySerializer, result);
    }

    @Test
    public void testCreateContextual_DefaultCaseReturnsThis() throws JsonMappingException {
        // This covers the final "return this" at the end of the method
        // which happens if shape is not numeric, not string/pattern/locale/timezone combo
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.OBJECT); // Not numeric, not string
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(false);
        when(format.hasTimeZone()).thenReturn(false);
        doReturn(format).when(spySerializer).findFormatOverrides(any(), any(), any());

        JsonSerializer<?> result = spySerializer.createContextual(serializers, property);

        assertSame(spySerializer, result);
    }
}
